SELECT ?ahu ?label ?comp WHERE {
  ?ahu a brick:AirHandlingUnit .
  ?ahu rdfs:label ?label .
  FILTER(contains(?label, "AHU03") || contains(str(?ahu), "AHU03"))
  OPTIONAL { ?ahu brick:hasPart ?comp }
}

SELECT ?ahu ?class ?label WHERE {
  ?ahu a ?class .
  FILTER(?class != brick:ElectricPower)
  ?ahu rdfs:label ?label .
}

